INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Netzwerkadresse immer 32 Bit lang ist?', 2, '[{"text": "Ja", "correct": true, "because": "IPv4 hat 32 Bit"}, {"text": "Nein", "correct": false, "because": "Standard für IPv4"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Bereich gehört zu privaten Netzwerken?', 3, '[{"text": "192.168.0.0", "correct": true, "because": "Private Klasse-C-Adresse"}, {"text": "1.2.3.4", "correct": false, "because": "Öffentlich"}, {"text": "255.255.255.255", "correct": false, "because": "Broadcast"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale hat eine typische Netzwerkadresse?', 5, '[{"text": "32-Bit-Länge", "correct": true, "because": "IPv4-Format"}, {"text": "Netzwerk- und Host-Teil", "correct": true, "because": "Trennt Bereiche"}, {"text": "Subnetzmaske", "correct": true, "because": "Definiert Netzwerke"}, {"text": "Farbcodierung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) 10.0.0.0 ist privat. b) 172.16.0.0 ist öffentlich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "172.16.0.0 ist privat"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich ein Netzwerk einrichte?', 4, '[{"text": "Subnetzmaske", "correct": false, "because": "Definiert Netzwerk"}, {"text": "Gateway", "correct": false, "because": "Routing notwendig"}, {"text": "Büroverschönerung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass jede Adresse öffentlich ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Private Bereiche existieren"}, {"text": "Ja", "correct": false, "because": "Falsch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Adressbereich beginnt mit 172 und ist privat?', 3, '[{"text": "172.16.0.0", "correct": true, "because": "Privatbereich Klasse B"}, {"text": "172.15.0.0", "correct": false, "because": "Nicht privat"}, {"text": "172.32.0.0", "correct": false, "because": "Nicht privat"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet Subnetting?', 5, '[{"text": "Effiziente Nutzung", "correct": true, "because": "Teilt Adressen"}, {"text": "Sicherheit", "correct": true, "because": "Isoliert Netzwerke"}, {"text": "Kleinere Netze", "correct": true, "because": "Bessere Verwaltung"}, {"text": "Farbanpassung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass a) 127.0.0.1 für Loopback ist und b) 192.168.1.1 öffentlich ist. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "192.168.1.1 ist privat"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um eine Netzwerkadresse zu bestimmen?', 4, '[{"text": "Subnetzmaske", "correct": false, "because": "Trennt Netzwerk"}, {"text": "IP-Bereich", "correct": false, "because": "Definiert Adresse"}, {"text": "Bürogestaltung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Hat jede Adresse 128 Bit?', 2, '[{"text": "Nein", "correct": true, "because": "IPv4 hat 32 Bit"}, {"text": "Ja", "correct": false, "because": "IPv6 hat 128 Bit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Bereiche sind für private Netzwerke reserviert?', 4, '[{"text": "10.0.0.0", "correct": true, "because": "Klasse A privat"}, {"text": "172.16.0.0", "correct": true, "because": "Klasse B privat"}, {"text": "8.8.8.8", "correct": false, "because": "Öffentlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass 255.255.255.255 eine normale Adresse ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Broadcast-Adresse"}, {"text": "Ja", "correct": false, "because": "Spezielle Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einer Netzwerkadresse?', 3, '[{"text": "Geräte identifizieren", "correct": true, "because": "Eindeutige Zuweisung"}, {"text": "Daten komprimieren", "correct": false, "because": "Anderer Zweck"}, {"text": "Design verbessern", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) 0.0.0.0 ist für unbekannte Netze. b) 169.254.0.0 ist öffentlich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "169.254.0.0 ist APIPA"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die Subnetzmaske?', 4, '[{"text": "Trennt Netzwerk und Host", "correct": true, "because": "Definiert Bereiche"}, {"text": "Verschlüsselt Daten", "correct": false, "because": "Nicht Zweck"}, {"text": "Farbt Daten", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Adresse wie 224.0.0.0 normal genutzt wird?', 2, '[{"text": "Nein", "correct": true, "because": "Multicast-Adresse"}, {"text": "Ja", "correct": false, "because": "Spezielle Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen eine Netzwerkadresse nützlich?', 5, '[{"text": "Eindeutigkeit", "correct": true, "because": "Identifiziert Geräte"}, {"text": "Subnetztrennung", "correct": true, "because": "Organisiert Netzwerke"}, {"text": "Kompatibilität", "correct": true, "because": "IPv4-Standard"}, {"text": "Schnelle Hardware", "correct": false, "because": "Kein Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist 169.254.1.1 eine private Adresse?', 3, '[{"text": "Ja", "correct": true, "because": "APIPA-Bereich"}, {"text": "Nein", "correct": false, "because": "Reserviert für APIPA"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zu einer typischen Netzwerkadresse?', 4, '[{"text": "192.168.1.10 im Heimnetzwerk", "correct": true, "because": "Private Adresse"}, {"text": "8.8.8.8 im LAN", "correct": false, "because": "Öffentlich"}, {"text": "255.255.255.255 für Einzelgerät", "correct": false, "because": "Broadcast"}]');
